// eslint-disable-next-line @typescript-eslint/no-namespace -- grandfathered code
export namespace RandomPCG32 {
	export class RandomState {
		state = 0x08f5dc87e5c07d8an;
		inc = 0x3n;
	}

	export function seed(value: number) {
		randomPCG32State.state = 0n;
		randomPCG32State.inc = 0x3n;
		rand();
		randomPCG32State.state += BigInt(value);
		rand();
	}

	export function rand(): number {
		const oldState: bigint = randomPCG32State.state;
		randomPCG32State.state =
			(((oldState * 6364136223846793005n) & 0xffffffffffffffffn) + randomPCG32State.inc) & 0xffffffffffffffffn;
		const xorshifted: bigint = (((oldState >> 18n) ^ oldState) >> 27n) & 0xffffffffn;
		const rot0: bigint = (oldState >> 59n) & 0xffffffffn;
		const rot1: bigint = (~rot0 + 1n) & 31n;
		const output: bigint = ((xorshifted >> rot0) | (xorshifted << rot1)) & 0xffffffffn;
		return Number(output);
	}

	export function fRand(strLog: string): number {
		//return rand() * (1.0 / 4294967296.0);
		return getRandomNumber(65535, strLog) / 65535.0;
	}

	declare abstract class TerrainBuilder {
		public static getRandomNumber(iRange: number, strLog: string): number;
	}

	export function getRandomNumber(iRange: number, strLog: string): number {
		// Try to use TerrainBuilder.getRandomNumber(), fallback if not available.
		if (typeof TerrainBuilder == "object" && typeof (TerrainBuilder as any).getRandomNumber == "function") {
			return TerrainBuilder.getRandomNumber(iRange, strLog);
		} else {
			return Math.floor((rand() & 65535) * (iRange / 65536));
		}
	}

	export function getState(): RandomState {
		return { state: randomPCG32State.state, inc: randomPCG32State.inc };
	}

	export function setState(state: RandomState) {
		randomPCG32State.state = state.state;
		randomPCG32State.inc = state.inc;
	}

	export const randomPCG32State: RandomState = new RandomState();
}

// eslint-disable-next-line @typescript-eslint/no-namespace -- grandfathered code
export namespace GameCoreRandom {
	const RANDOM_A = 1103515245n;
	const RANDOM_C = 12345n;
	const RANDOM_SHIFT = 16n;

	// 0: off, 1: state changes, 2: every number generated
	const LOG_LEVEL: 0 | 1 | 2 = 1;

	export class RandomState {
		state = 0x08f5dc87e5c07d8an;
	}

	export function seed(value: number) {
		randomState.state = BigInt(value);
		if (LOG_LEVEL >= 1) {
			console.log("GameCoreRandom: setting seed to " + value);
		}
	}

	export function rand(): bigint {
		randomState.state = (RANDOM_A * randomState.state + RANDOM_C) & 0xffffffffn;
		return (randomState.state >> RANDOM_SHIFT) & 0xffffn;
	}

	export function fRand(strLog: string): number {
		return getRandomNumber(65535, strLog) / 65535.0;
	}

	export function getRandomNumber(iRange: number, strLog: string): number {
		// Try to use TerrainBuilder.getRandomNumber(), fallback if not available.
		iRange = Math.floor(iRange);
		let num = 0;
		if (typeof TerrainBuilder == "object" && typeof (TerrainBuilder as any).getRandomNumber == "function") {
			num = TerrainBuilder.getRandomNumber(iRange, strLog);
		} else {
			num = Math.floor(Number(rand()) * (iRange / 65536));
		}
		if (LOG_LEVEL >= 2) {
			console.log("GameCoreRandom: getRandomNumber(" + iRange + ', "' + strLog + '") = ' + num);
		}
		return num;
	}

	export function randomNormal(mean: number, stdDev: number, strLog: string): number {
		// Box-Muller transform
		const u1 = fRand(strLog + " Normal u1");
		const u2 = fRand(strLog + " Normal u2");
		const z0 = Math.sqrt(-2.0 * Math.log(Math.max(u1, 0.000001))) * Math.cos(2.0 * Math.PI * u2);
		return z0 * stdDev + mean;
	}

	export function randomNormal2(mean: number, stdDevBelow: number, stdDevAbove: number, strLog: string): number {
		// Box-Muller transform, separate std dev for above and below mean
		const u1 = fRand(strLog + " Normal u1");
		const u2 = fRand(strLog + " Normal u2");
		const z0 = Math.sqrt(-2.0 * Math.log(Math.max(u1, 0.000001))) * Math.cos(2.0 * Math.PI * u2);
		return z0 * (z0 < 0 ? stdDevBelow : stdDevAbove) + mean;
	}

	export function getState(): RandomState {
		if (LOG_LEVEL >= 1) {
			console.log("GameCoreRandom: getState() called with current state " + randomState.state);
		}
		return { state: randomState.state };
	}

	export function setState(state: RandomState) {
		if (LOG_LEVEL >= 1) {
			console.log("GameCoreRandom: setState(" + state.state + ")");
		}
		randomState.state = state.state;
	}

	export const randomState: RandomState = new RandomState();
}

export import RandomImpl = GameCoreRandom;
